    .wl-item .last { font-family: var(--font-mono); text-align: right; }
    .wl-item .chg-pct { font-family: var(--font-mono); text-align: right; font-size: 0.6875rem; }

    /* Stock Detail Panel */
    .detail-panel {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--bg-card);
      border-top: 1px solid var(--border);
      z-index: 50;
      transition: transform 300ms ease-out;
    }
    .detail-panel.collapsed { transform: translateY(calc(100% - 40px)); }
    .detail-panel-toggle {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.5rem 1rem;
      border-bottom: 1px solid var(--border);
      cursor: pointer;
    }
    .detail-panel-toggle h3 { font-size: 0.875rem; font-weight: 700; }
    .detail-panel-toggle .toggle-icon { color: var(--text-muted); font-size: 0.75rem; transition: transform 200ms; }
    .detail-panel.collapsed .toggle-icon { transform: rotate(180deg); }

    .detail-content {
      max-height: 300px;
      overflow-y: auto;
      padding: 1rem;
    }
    .detail-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: 1rem;
    }
    @media (max-width: 768px) { .detail-grid { grid-template-columns: 1fr 1fr; } }
    .detail-stat .label { font-size: 0.6875rem; color: var(--text-muted); margin-bottom: 0.125rem; }
    .detail-stat .value { font-size: 0.875rem; font-weight: 600; }

    .detail-headline {
      margin-top: 1rem;
      padding: 0.75rem;
      background: var(--bg-elevated);
      border-radius: var(--radius);
      font-size: 0.8125rem;
      line-height: 1.5;
    }
    .detail-headline .source { font-size: 0.6875rem; color: var(--text-muted); margin-top: 0.25rem; }

    /* Financials Panel */
    .financials-panel {
      max-width: 1400px;
      margin: 0 auto;
      padding: 1.5rem;
    }
    .financials-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem;
    }
    @media (max-width: 768px) { .financials-grid { grid-template-columns: 1fr; } }

    .fin-table {
      width: 100%;
      border-collapse: collapse;
    }
    .fin-table th {
      text-align: left;
      padding: 0.5rem 0.75rem;
      font-size: 0.6875rem;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      border-bottom: 1px solid var(--border);
    }
    .fin-table td {
      padding: 0.5rem 0.75rem;
      font-size: 0.8125rem;
      border-bottom: 1px solid var(--border);
    }
    .fin-table td:last-child {
      font-family: var(--font-mono);
      text-align: right;
    }
    .fin-table tr:hover td { background: rgba(255,255,255,0.02); }

    .perf-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.75rem;
    }
    .perf-item {
      background: var(--bg-primary);
      border-radius: var(--radius);
      padding: 0.75rem;
    }
    .perf-item .label { font-size: 0.6875rem; color: var(--text-muted); }
    .perf-item .value { font-size: 1rem; font-weight: 700; margin-top: 0.25rem; }

    /* Chart with margin for detail panel */
    .chart-workspace { padding-bottom: 50px; }
  </style>
</head>
