<script>
function switchBrokerCat(el, cat) {
  document.querySelectorAll('.cat-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');

  // Hide all broker lists
  document.getElementById('broker-list-all').style.display = 'none';
  document.querySelectorAll('.broker-category-content').forEach(c => c.style.display = 'none');

  if (cat === 'all') {
    document.getElementById('broker-list-all').style.display = 'flex';
  } else {
    const list = document.getElementById('broker-list-' + cat);
    if (list) list.style.display = 'flex';
  }
}

function switchSortTab(el, type) {
  document.querySelectorAll('.sort-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');

  if (type === 'best') {
    // Sort by rating (already in order for demo)
    const allList = document.getElementById('broker-list-all');
    const cards = Array.from(allList.querySelectorAll('.broker-card'));
    cards.sort((a, b) => {
      const scoreA = parseFloat(a.querySelector('.score').textContent);
      const scoreB = parseFloat(b.querySelector('.score').textContent);
      return scoreB - scoreA;
    });
    cards.forEach(card => allList.appendChild(card));
  }
}
</script>
